mapper.select:
SELECT SD.DEVICE_NAME, SD.DEVICE_TYPE, SDT.DEVICE_CODE, SDT.CARD_NO, SDT.IMAGE_ID, SDT.SERVICE_TYPE, SA.AREA_NAME, SDT.GENERAL, SDT.CREATE_TIME, SDT.START_TIME, SDT.OVER_TIME FROM SMT_TASK_DOWN_RECORD SDT LEFT JOIN SMT_DEVICE SD ON SD.ID = SDT.DEVICE_CODE LEFT JOIN SMT_DEVICE_AREA SDA ON SDA.DEVICE_ID = SDT.DEVICE_CODE LEFT JOIN SMT_AREA SA ON SA.ID = SDA.AREA_ID WHERE SDT.ACTION = 1 AND SD.DEVICE_NAME IS NOT NULL
AND SD.ID = #{query.deviceId}
AND SD.DEVICE_NAME LIKE CONCAT('%', CONCAT(#{query.deviceName}, '%'))
AND SDT.GENERAL LIKE CONCAT('%', CONCAT(#{query.badge}, '%'))
AND SDT.DEVICE_TYPE = #{query.deviceType}
AND SDA.AREA_ID IN ( SELECT SA."ID" FROM SMT_AREA SA
AND SA.PARK_ID = #{query.parkId}
AND SA.PID = #{query.parAreaId}
AND SA."ID" = #{query.areaId}
)
AND SD.PARK_ID IN
#{tempId}
ORDER BY SDT.CREATE_TIME DESC

SELECT SD.DEVICE_NAME, SD.DEVICE_TYPE, SDT.DEVICE_CODE, SDT.CARD_NO, SDT.IMAGE_ID, SDT.SERVICE_TYPE, SA.AREA_NAME, SDT.GENERAL, SDT.CREATE_TIME, SDT.START_TIME, SDT.OVER_TIME FROM SMT_ISC_DOWN_RECORD SDT LEFT JOIN SMT_DEVICE SD ON SD.ID = SDT.DEVICE_CODE LEFT JOIN SMT_DEVICE_AREA SDA ON SDA.DEVICE_ID = SDT.DEVICE_CODE LEFT JOIN SMT_AREA SA ON SA.ID = SDA.AREA_ID WHERE SDT.ACTION = 1 AND SD.DEVICE_NAME IS NOT NULL
AND SD.ID = #{query.deviceId}
AND SDT.GENERAL LIKE CONCAT('%', CONCAT(#{query.badge}, '%'))
AND SD.DEVICE_NAME LIKE CONCAT('%', CONCAT(#{query.deviceName}, '%'))
AND SDT.DEVICE_TYPE = #{query.deviceType}
AND SDA.AREA_ID IN ( SELECT SA."ID" FROM SMT_AREA SA
AND SA.PARK_ID = #{query.parkId}
AND SA.PID = #{query.parAreaId}
AND SA."ID" = #{query.areaId}
)
AND SD.PARK_ID IN
#{tempId}
ORDER BY SDT.CREATE_TIME DESC
